import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { CalendarDays, Download, Package, ShoppingBag, TrendingUp, Users, Wallet } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { AreaChart, Donut, PageHeader, Progress, StatCard, cn } from '../lib/ui';
import { formatShort, formatUZS, monthlySeries, salesSeries } from '../lib/mock';

export const Reports = () => {
  const { t } = useTranslation();
  const { orders, products, categories, customers, notify } = useAdmin();
  const [range, setRange] = useState<'week' | 'month' | 'year'>('month');

  const revenue = orders.filter((o) => o.status !== 'cancelled').reduce((s, o) => s + o.total, 0);
  const delivered = orders.filter((o) => o.status === 'delivered').length;
  const avgOrder = orders.length ? revenue / orders.length : 0;
  const series = range === 'week' ? salesSeries : monthlySeries;

  const categoryData = categories.map((c) => {
    const list = products.filter((p) => p.categoryId === c.id);
    return { label: c.name, value: list.reduce((s, p) => s + p.sold, 0), color: c.color };
  });
  const categoryTotal = categoryData.reduce((s, c) => s + c.value, 0);

  const top = [...products].sort((a, b) => b.sold - a.sold).slice(0, 6);

  const exportReport = () => {
    const rows = [
      ['MaxSHOP report', new Date().toISOString().slice(0, 10)],
      ['Revenue', String(revenue)],
      ['Orders', String(orders.length)],
      ['Delivered', String(delivered)],
      ['Avg order', String(Math.round(avgOrder))],
      ['Customers', String(customers.length)],
      [],
      ['Product', 'Sold', 'Stock', 'Revenue'],
      ...top.map((p) => [p.name, String(p.sold), String(p.stock), String(p.sold * p.price)]),
    ];
    const csv = rows.map((r) => r.map((v) => `"${v}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'maxshop-report.csv';
    a.click();
    URL.revokeObjectURL(url);
    notify('Hisobot yuklab olindi', 'info');
  };

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('reportsTitle')}
        subtitle={t('reportsSubtitle')}
        action={
          <>
            <div className="flex rounded-xl border p-1" style={{ borderColor: 'var(--border)', background: 'var(--surface)' }}>
              {(['week', 'month', 'year'] as const).map((r) => (
                <button
                  key={r}
                  onClick={() => setRange(r)}
                  className={cn('rounded-lg px-3 py-1.5 text-xs font-bold transition', range === r ? 'bg-brand-600 text-white' : 'text-[var(--muted)]')}
                >
                  {r === 'week' ? t('week') : r === 'month' ? t('month') : 'Yil'}
                </button>
              ))}
            </div>
            <button className="btn-primary btn-sm" onClick={exportReport}><Download size={15} /> {t('export')}</button>
          </>
        }
      />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label={t('revenue')} value={formatShort(revenue) + " so'm"} icon={<Wallet size={20} />} delta={{ value: '14.2% o\'sish', positive: true }} />
        <StatCard label={t('ordersCount')} value={String(orders.length)} icon={<ShoppingBag size={20} />} tone="sky" delta={{ value: '9.8% o\'sish', positive: true }} />
        <StatCard label={t('customersCount')} value={String(customers.length)} icon={<Users size={20} />} tone="violet" delta={{ value: '4 yangi', positive: true }} />
        <StatCard label={t('avgOrder')} value={formatShort(avgOrder) + " so'm"} icon={<TrendingUp size={20} />} tone="amber" delta={{ value: '2.1% pasayish', positive: false }} />
      </div>

      <div className="grid grid-cols-1 gap-5 xl:grid-cols-3">
        <div className="card p-5 xl:col-span-2">
          <div className="mb-4 flex items-center justify-between">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('dailySales')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Daromad dinamikasi (mln so'm)</p>
            </div>
            <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300"><CalendarDays size={12} /> {range === 'week' ? '7 kun' : '12 oy'}</span>
          </div>
          <AreaChart data={series} height={280} />
          <div className="mt-4 grid grid-cols-3 gap-3">
            <div className="card-soft p-3">
              <p className="text-[10px] font-bold text-[var(--muted)]">Eng yuqori kun</p>
              <p className="mt-1 font-display text-base font-extrabold">Shanba · 12.4 mln</p>
            </div>
            <div className="card-soft p-3">
              <p className="text-[10px] font-bold text-[var(--muted)]">O'rtacha kunlik</p>
              <p className="mt-1 font-display text-base font-extrabold">8.5 mln</p>
            </div>
            <div className="card-soft p-3">
              <p className="text-[10px] font-bold text-[var(--muted)]">Yetkazilgan</p>
              <p className="mt-1 font-display text-base font-extrabold">{delivered} ta</p>
            </div>
          </div>
        </div>

        <div className="card p-5">
          <div className="mb-4">
            <h2 className="font-display text-lg font-extrabold">{t('categoryShare')}</h2>
            <p className="mt-0.5 text-xs text-[var(--muted)]">Sotuvlar bo'yicha ulush</p>
          </div>
          <Donut
            total={categoryTotal}
            centerLabel="sotilgan"
            centerValue={formatShort(categoryTotal)}
            segments={categoryData.slice(0, 6)}
          />
        </div>
      </div>

      <div className="mt-5 grid grid-cols-1 gap-5 xl:grid-cols-3">
        <div className="card p-5 xl:col-span-2">
          <div className="mb-4 flex items-center justify-between">
            <div>
              <h2 className="font-display text-lg font-extrabold">{t('productPerformance')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Eng ko'p sotilgan mahsulotlar</p>
            </div>
            <Package size={18} className="text-[var(--muted)]" />
          </div>
          <div className="table-wrap">
            <table className="data-table min-w-[600px]">
              <thead>
                <tr>
                  <th>{t('product')}</th>
                  <th>Sotilgan</th>
                  <th>Daromad</th>
                  <th>Zaxira</th>
                  <th className="w-40">Ulush</th>
                </tr>
              </thead>
              <tbody>
                {top.map((p) => (
                  <tr key={p.id}>
                    <td>
                      <div className="flex items-center gap-2.5">
                        <span className={cn('flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br text-base', p.gradient)}>{p.emoji}</span>
                        <div>
                          <p className="text-xs font-extrabold">{p.name}</p>
                          <p className="text-[10px] text-[var(--muted)]">{p.sku}</p>
                        </div>
                      </div>
                    </td>
                    <td className="text-xs font-bold">{p.sold} ta</td>
                    <td className="text-xs font-extrabold">{formatUZS(p.sold * p.price)}</td>
                    <td className="text-xs">{p.stock} {p.unit}</td>
                    <td><Progress value={(p.sold / top[0].sold) * 100} /></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-4">
          <div className="card p-5">
            <h3 className="font-display text-base font-extrabold">Buyurtma sifat ko'rsatkichlari</h3>
            <div className="mt-4 space-y-3">
              {[
                { label: 'Muvaffaqiyatli yetkazildi', value: 92, tone: 'brand' as const },
                { label: 'Vaqtida yetkazildi', value: 87, tone: 'sky' as const },
                { label: 'Bekor qilindi', value: 6, tone: 'rose' as const },
                { label: 'Qaytarildi', value: 3, tone: 'amber' as const },
              ].map((r) => (
                <div key={r.label}>
                  <div className="mb-1 flex justify-between text-[11px] font-bold">
                    <span className="text-[var(--muted)]">{r.label}</span>
                    <span>{r.value}%</span>
                  </div>
                  <Progress value={r.value} tone={r.tone} />
                </div>
              ))}
            </div>
          </div>
          <div className="card p-5">
            <h3 className="font-display text-base font-extrabold">Mijozlar tahlili</h3>
            <div className="mt-3 space-y-2.5 text-xs">
              <div className="flex justify-between"><span className="text-[var(--muted)]">Qaytgan mijozlar</span><b>68%</b></div>
              <div className="flex justify-between"><span className="text-[var(--muted)]">Yangi mijozlar</span><b>32%</b></div>
              <div className="flex justify-between"><span className="text-[var(--muted)]">VIP mijozlar</span><b>{customers.filter((c) => c.vip).length}</b></div>
              <div className="flex justify-between"><span className="text-[var(--muted)]">O'rtacha xarid</span><b>{formatUZS(avgOrder)}</b></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
